APISIX Anthropic 与 OpenAI 协议互转插件：支持流式、思考、工具调用与多模态 AI时代高效设计开发：Anthropic → OpenAI 协议转换插件实战一、参考已有实现复用 Higress、LiteLLM 等相似项目的代码实现，让 AI 直接参考。 二、准备测试用例整理 CURL 示例等场景，让 AI 自行校验验证结果。 三、明确功能边界 阶段 转换内容 请求 Anthropic Messages API → OpenAI Chat Completions 响应 OpenAI Chat Completions → Anthropic Messages API 支持 非流式&#x2F;流式、thinking、tool_use、多模态图片 四、Vibe Coding---- APISIX Plugin: claude2openai-- 参考实现: Higress ai-proxy provider/claude_to_openai.go---- 功能：-- 1. 请求阶段：将 Claude Messages API 请求转换为 OpenAI Chat Completions 请求-- 2. 响应阶段：将 OpenAI Chat Completions 响应转换为 Claude Messages API 响应-- 支持：非流式、流式、thinking、tool_use、多模态图片--local core = require(&quot;apisix.core&quot;)local cjson = require(&quot;cjson.safe&quot;)local ngx = ngxlocal pairs = pairslocal ipairs = ipairslocal type = typelocal table_insert = table.insertlocal table_concat = table.concatlocal string_sub = string.sublocal string_find = string.findlocal ngx_now = ngx.nowlocal plugin_name = &quot;jiankunking-claude2openai&quot;local schema = &#123; type = &quot;object&quot;, properties = &#123; target_model = &#123; type = &quot;string&quot;, description = &quot;Override the model name sent to OpenAI backend&quot; &#125;, &#125;,&#125;local _M = &#123; version = 0.1, priority = 2650, -- 在 consumer-restriction(2640) 和 key-auth(2500) 之前执行 name = plugin_name, schema = schema,&#125;function _M.check_schema(conf) return core.schema.check(schema, conf)end-------------------------------------------------------------------------- 工具函数-------------------------------------------------------------------------- OpenAI finish_reason -&gt; Claude stop_reason (参考 Higress openAIFinishReasonToClaude)local function openai_finish_reason_to_claude(reason) if not reason or reason == cjson.null then return &quot;end_turn&quot; end local mapping = &#123; stop = &quot;end_turn&quot;, length = &quot;max_tokens&quot;, tool_calls = &quot;tool_use&quot;, content_filter = &quot;end_turn&quot;, &#125; return mapping[reason] or reasonend-- 移除 x-anthropic-billing-header 中的动态 cch 字段以支持 prompt caching-- 参考 Higress stripCchFromBillingHeader-- cch 值每次请求都会变化，如果不移除会导致缓存失效local function strip_cch_from_billing_header(text) if type(text) ~= &quot;string&quot; then return text end local prefix = &quot;x-anthropic-billing-header:&quot; if string_sub(text, 1, #prefix) ~= prefix then return text end -- 循环移除所有&quot;; cch=xxx&quot; 模式 local result = text while true do local cch_start = string_find(result, &quot;; cch=&quot;, 1, true) if not cch_start then break end local after = cch_start + 2 -- skip &quot;; &quot; local semi_pos = string_find(result, &quot;;&quot;, after, true) if not semi_pos then -- cch 在末尾，直接截断 result = string_sub(result, 1, cch_start - 1) else -- cch 后面还有内容，移除 &quot;; cch=xxx&quot; 部分 result = string_sub(result, 1, cch_start - 1) .. string_sub(result, semi_pos) end end return resultend-- Claude content blocks 中提取纯文本部分local function extract_text_parts(content_array) local parts = &#123;&#125; if type(content_array) ~= &quot;table&quot; then return parts end for _, block in ipairs(content_array) do if block.type == &quot;text&quot; and block.text then table_insert(parts, block.text) end end return partsend-------------------------------------------------------------------------- 请求转换: Claude Messages -&gt; OpenAI Chat Completions-- 参Higress ConvertClaudeRequestToOpenAI-------------------------------------------------------------------------- 转换 Claude content blocks 数组为 OpenAI 格式-- 返回 &#123; text_parts, tool_calls, tool_results, openai_contents &#125;local function convert_content_array(content_array) local result = &#123; text_parts = &#123;&#125;, tool_calls = &#123;&#125;, tool_results = &#123;&#125;, openai_contents = &#123;&#125;, &#125; if type(content_array) ~= &quot;table&quot; then return result end for _, block in ipairs(content_array) do if block.type == &quot;text&quot; and block.text then local processed_text = strip_cch_from_billing_header(block.text) table_insert(result.text_parts, processed_text) local openai_content = &#123; type = &quot;text&quot;, text = processed_text &#125; -- 透传 cache_control 以支持 prompt caching if block.cache_control then openai_content.cache_control = block.cache_control end table_insert(result.openai_contents, openai_content) elseif (block.type == &quot;image&quot; or block.type == &quot;document&quot;) and block.source then -- Claude: &#123;type:&quot;image&quot;/&quot;document&quot;, source:&#123;type:&quot;base64&quot;, media_type:&quot;...&quot;, data:&quot;...&quot;&#125;&#125; -- OpenAI: &#123;type:&quot;image_url&quot;, image_url:&#123;url:&quot;data:...;base64,...&quot;&#125;&#125; local img_obj if block.source.type == &quot;base64&quot; then img_obj = &#123; type = &quot;image_url&quot;, image_url = &#123; url = &quot;data:&quot; .. (block.source.media_type or &quot;image/png&quot;) .. &quot;;base64,&quot; .. block.source.data &#125; &#125; elseif block.source.type == &quot;url&quot; then img_obj = &#123; type = &quot;image_url&quot;, image_url = &#123; url = block.source.url &#125; &#125; end if img_obj then if block.cache_control then img_obj.cache_control = block.cache_control end table_insert(result.openai_contents, img_obj) end elseif block.type == &quot;thinking&quot; and block.thinking then -- Claude assistant 历史消息中的 thinking block -&gt; OpenAI thinking block local thinking_obj = &#123; type = &quot;thinking&quot;, thinking = block.thinking, signature = block.signature or &quot;&quot; &#125; table_insert(result.openai_contents, thinking_obj) elseif block.type == &quot;redacted_thinking&quot; then -- Claude redacted_thinking block -&gt; 透传 table_insert(result.openai_contents, &#123; type = &quot;redacted_thinking&quot;, data = block.data or &quot;&quot; &#125;) elseif block.type == &quot;tool_use&quot; then -- Claude tool_use -&gt; OpenAI tool_calls if block.id and block.name then table_insert(result.tool_calls, &#123; id = block.id, type = &quot;function&quot;, [&quot;function&quot;] = &#123; name = block.name, arguments = cjson.encode(block.input or &#123;&#125;) or &quot;&#123;&#125;&quot; &#125; &#125;) core.log.debug(&quot;[Claude-&gt;OpenAI] Converted tool_use to tool_call: &quot;, block.name) end elseif block.type == &quot;tool_result&quot; then table_insert(result.tool_results, block) core.log.debug(&quot;[Claude-&gt;OpenAI] Found tool_result for tool_use_id: &quot;, block.tool_use_id or &quot;&quot;) end end return resultendlocal function convert_claude_request_to_openai(claude_body, conf) core.log.debug(&quot;[Claude-&gt;OpenAI] Original Claude request body: &quot;, cjson.encode(claude_body)) local openai_body = &#123; model = conf.target_model or claude_body.model, max_tokens = claude_body.max_tokens, temperature = claude_body.temperature, top_p = claude_body.top_p, stop = claude_body.stop_sequences, stream = claude_body.stream, &#125; if openai_body.stream then openai_body.stream_options = &#123; include_usage = true &#125; end local messages = &#123;&#125; -- system: Claude 顶层字段 -&gt; OpenAI system message（插入到 messages 最前面） if claude_body.system then if type(claude_body.system) == &quot;string&quot; then table_insert(messages, &#123; role = &quot;system&quot;, content = strip_cch_from_billing_header(claude_body.system) &#125;) elseif type(claude_body.system) == &quot;table&quot; then -- system 可以是 content blocks 数组 -- 参考 litellm: 过滤掉 x-anthropic-billing-header 开头的 block，空文本 block 也跳过 local sys_contents = &#123;&#125; for _, block in ipairs(claude_body.system) do if block.type == &quot;text&quot; and block.text then if block.text == &quot;&quot; then -- 跳过空文本（Anthropic API 会报错） elseif string_sub(block.text, 1, 28) == &quot;x-anthropic-billing-header:&quot; then -- 跳过 billing header metadata core.log.debug(&quot;[Claude-&gt;OpenAI] Skipping billing header system block&quot;) else local sys_block = &#123; type = &quot;text&quot;, text = strip_cch_from_billing_header(block.text) &#125; if block.cache_control then sys_block.cache_control = block.cache_control end table_insert(sys_contents, sys_block) end end end if #sys_contents &gt; 0 then table_insert(messages, &#123; role = &quot;system&quot;, content = sys_contents &#125;) end end end -- messages 转换 if claude_body.messages then for _, msg in ipairs(claude_body.messages) do if type(msg.content) == &quot;string&quot; then -- 简单文本 table_insert(messages, &#123; role = msg.role, content = msg.content &#125;) elseif type(msg.content) == &quot;table&quot; then local conv = convert_content_array(msg.content) -- 有 tool_calls（assistant 消息中的 tool_use） if #conv.tool_calls &gt; 0 then local openai_msg = &#123; role = msg.role, tool_calls = conv.tool_calls, &#125; if #conv.text_parts &gt; 0 then openai_msg.content = table_concat(conv.text_parts, &quot;

&quot;) else openai_msg.content = cjson.null end table_insert(messages, openai_msg) end -- 有 tool_results（user 消息中的 tool_result） if #conv.tool_results &gt; 0 then for _, tr in ipairs(conv.tool_results) do local tool_content if type(tr.content) == &quot;string&quot; then tool_content = tr.content elseif type(tr.content) == &quot;table&quot; then -- 参考 litellm: tool_result.content 可能包含 text + image 混合内容 local content_parts = &#123;&#125; local has_non_text = false for _, c in ipairs(tr.content) do if type(c) == &quot;string&quot; then table_insert(content_parts, &#123; type = &quot;text&quot;, text = c &#125;) elseif type(c) == &quot;table&quot; then if c.type == &quot;text&quot; then table_insert(content_parts, &#123; type = &quot;text&quot;, text = c.text or &quot;&quot; &#125;) elseif (c.type == &quot;image&quot; or c.type == &quot;document&quot;) and c.source then has_non_text = true if c.source.type == &quot;base64&quot; then table_insert(content_parts, &#123; type = &quot;image_url&quot;, image_url = &#123; url = &quot;data:&quot; .. (c.source.media_type or &quot;image/png&quot;) .. &quot;;base64,&quot; .. c.source.data &#125; &#125;) elseif c.source.type == &quot;url&quot; then table_insert(content_parts, &#123; type = &quot;image_url&quot;, image_url = &#123; url = c.source.url &#125; &#125;) end end end end -- 如果只有纯文本，合并为 string（兼容性更好） if not has_non_text then local texts = &#123;&#125; for _, p in ipairs(content_parts) do if p.type == &quot;text&quot; then table_insert(texts, p.text) end end tool_content = table_concat(texts, &quot;
&quot;) else -- 混合内容（text + image），保持数组格式 tool_content = content_parts end else tool_content = &quot;&quot; end table_insert(messages, &#123; role = &quot;tool&quot;, tool_call_id = tr.tool_use_id, content = tool_content &#125;) end -- tool_result 旁边可能还有 text if #conv.text_parts &gt; 0 then table_insert(messages, &#123; role = msg.role, content = table_concat(conv.text_parts, &quot;

&quot;) &#125;) end end -- 普通内容（无 tool_calls 也无 tool_results） if #conv.tool_calls == 0 and #conv.tool_results == 0 then -- 如果只有 text，简化为 string if #conv.openai_contents == 1 and conv.openai_contents[1].type == &quot;text&quot; then table_insert(messages, &#123; role = msg.role, content = conv.openai_contents[1].text &#125;) else table_insert(messages, &#123; role = msg.role, content = conv.openai_contents &#125;) end end end end end openai_body.messages = messages -- tools 转换: Claude &#123;name, description, input_schema&#125; -&gt; OpenAI &#123;type, function&#125; if claude_body.tools then local openai_tools = &#123;&#125; for _, tool in ipairs(claude_body.tools) do table_insert(openai_tools, &#123; type = &quot;function&quot;, [&quot;function&quot;] = &#123; name = tool.name, description = tool.description, parameters = tool.input_schema &#125; &#125;) end openai_body.tools = openai_tools end -- tool_choice 转换 if claude_body.tool_choice then local tc = claude_body.tool_choice if tc.type == &quot;auto&quot; then openai_body.tool_choice = &quot;auto&quot; elseif tc.type == &quot;any&quot; then openai_body.tool_choice = &quot;required&quot; elseif tc.type == &quot;tool&quot; and tc.name then openai_body.tool_choice = &#123; type = &quot;function&quot;, [&quot;function&quot;] = &#123; nam

