equestOptions;import org.elasticsearch.client.RestClient;import org.elasticsearch.client.RestClientBuilder;import org.elasticsearch.client.RestHighLevelClient;import org.elasticsearch.client.indices.CreateIndexRequest;import org.elasticsearch.client.indices.CreateIndexResponse;import org.elasticsearch.common.settings.Settings;import org.elasticsearch.common.xcontent.XContentType;import javax.net.ssl.SSLContext;import java.io.File;import java.io.IOException;import java.security.KeyManagementException;import java.security.KeyStoreException;import java.security.NoSuchAlgorithmException;import java.security.cert.CertificateException;import java.util.HashMap;import java.util.Map;/** * @Author: jiankunking * @Date: 2019/8/27 15:32 * @Description: */public class es &#123; public static void main(String[] args) throws KeyStoreException, IOException, NoSuchAlgorithmException, KeyManagementException, CertificateException &#123; CredentialsProvider credentialsProvider = new BasicCredentialsProvider(); credentialsProvider.setCredentials(AuthScope.ANY, new UsernamePasswordCredentials(&quot;elastic&quot;, &quot;jiankunking&quot;)); SSLContext sslContext = SSLContexts.custom() .loadTrustMaterial(new File(&quot;I:\certs\my_keystore.jks&quot;)) .build(); String host = &quot;es.jiankunking.com&quot;; int port = 9200; String scheme = &quot;https&quot;; String indexName = &quot;twitter2&quot;; RestClientBuilder restClientBuilder = RestClient.builder(new HttpHost(host, port, scheme)).setHttpClientConfigCallback(httpClientBuilder -&gt; httpClientBuilder .setDefaultCredentialsProvider(credentialsProvider) .setSSLContext(sslContext) ); // 到这里RestHighLevelClient已经初始化完成，下面的创建索引是测试 RestHighLevelClient restHighLevelClient = new RestHighLevelClient(restClientBuilder); // 创建索引请求 CreateIndexRequest request = new CreateIndexRequest(indexName); request.settings(Settings.builder() .put(&quot;index.number_of_shards&quot;, 3) .put(&quot;index.number_of_replicas&quot;, 2) ); request.mapping( &quot;&#12